// Helper — get the data URL for a template ID
export function getTemplateDataUrl(templateId) {
  return TEMPLATE_IMAGES[templateId]?.dataUrl ?? null;
}

// Helper — get the Gemini Vision message part for a template
// Use this to send the reference image to Gemini as an inline image part
export function getTemplateVisionPart(templateId) {
  const img = TEMPLATE_IMAGES[templateId];
  if (!img) return null;
  return {
    inline_data: {
      mime_type: img.mime,
      data: img.b64,
    }
  };
}
